<template><main><h1>订单付款核验</h1><el-alert :title="message" :type="status==='PAID'?'success':'info'" :closable="false"/><p>订单：{{orderId||'未提供'}}</p><p v-if="provider">付款渠道：{{provider==='ALIPAY_SANDBOX'?'支付宝沙箱':provider==='LOCAL_DEMO'?'本地教学演示':provider}}</p><p>此页仅依据服务器核验结果显示状态，浏览器跳转参数不作为付款凭证。</p><el-button :loading="busy" @click="check">重新核验</el-button><el-button @click="router.push('/health-shop')">返回商城</el-button></main></template>
<script setup>
import{ref,onMounted,onBeforeUnmount}from'vue';import{useRoute,useRouter}from'vue-router';import{call}from'@/api/health';const route=useRoute(),router=useRouter(),orderId=String(route.query.out_trade_no||''),status=ref(''),provider=ref(''),message=ref('等待服务器确认付款结果'),busy=ref(false);let timer,attempts=0;
async function check(){if(!/^[A-Za-z0-9_-]{1,64}$/.test(orderId)){message.value='缺少有效订单号，请回商城查看订单';return}busy.value=true;try{const r=(await call('shop/orders/'+orderId+'/payment-status')).data;status.value=r.status;provider.value=r.provider;message.value=r.status==='PAID'?'服务器已确认订单结算':r.status==='RESERVED'?'尚未收到有效付款通知，可稍后重新核验':'订单已取消或到期，若沙箱已付款请保留交易号联系核对';}catch{message.value='暂时无法核验，请确认已登录且订单属于本人';}finally{busy.value=false}}
onMounted(async()=>{await check();timer=setInterval(async()=>{if(++attempts>=12||status.value==='PAID'){clearInterval(timer);return}await check()},5000)});onBeforeUnmount(()=>clearInterval(timer));
</script><style scoped>main{max-width:850px;margin:60px auto;padding:24px}p{line-height:1.8}</style>
